// === Tab: spCode.js ===

// www.shaderpark.com
// All the code below is javascript that's compiled into a shader
const spCode =  `

	const colorMap = [
    [1,			1,		1],  // rgb权重（突变颜色） 0~2
    [0.6,		0.2,		0.5]   // rgb偏移(中心球默认颜色)0~1
	]
	const speed = 1.1

  setMaxIterations(8);
  let click = input();
	let buttonHover = input();
  let offset = .1//input(0.08, 0, 0.1);
  function fbm(p) {
    return vec3(
      noise(p),
      noise(p+offset),
      noise(p+offset*2),
    )
  }

  let s = getRayDirection();
  let n = sin(fbm(s+vec3(0, 0, -time * speed))*2)*.5+.75;
  n = pow(n, vec3(8));


	function toX(n){
		return n.x*colorMap[0][0] + colorMap[1][0]
	}
	function toY(n){
		return n.y*colorMap[0][1] + colorMap[1][1]
	}
	function toZ(n){
		return n.z*colorMap[0][2] + colorMap[1][2]
	}
  n = vec3(toX(n), toY(n), toZ(n))

  color(n)
  let scale =.5+n.x*.05;
	shape(() => {
		rotateX(PI/2);
		rotateX(mouse.x* click)
		rotateZ(-1*mouse.y* click)
		//where you change
		torus(scale, 0.02) // 圆环外内径
		reset();
		mixGeo(click)

		sphere(scale);	// 随机突变大小
	})()
  blend(1.2)	// 鼠标冒出气泡大小
  displace(mouse.x*2, mouse.y, 0)

  sphere(.05) // 相对于页面宽度的直径百分百
`;


